import numpy as np
def card_scores(X,W):
    X,W=np.asarray(X),np.asarray(W)
    if X.ndim!=2 or W.ndim!=2 or X.shape[1]!=W.shape[0]:
        raise ValueError('Need compatible 2D matrices')
    return X @ W

import numpy as np
def nearest(table,query):
    table=np.asarray(table,dtype=float)
    query=np.asarray(query,dtype=float)
    scores=[]
    for row in table:
        den=np.linalg.norm(row)*np.linalg.norm(query)
        scores.append(float(row @ query/den) if den else 0.0)
    return int(np.argmax(scores))
